class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')

        # dp[i][j] = min cost to paint houses 0..i such that house i has color j
        dp = [[INF] * 3 for _ in range(n)]

        # Base case: first house
        for j in range(3):
            dp[0][j] = cost[0][j]

        for i in range(1, n):
            for j in range(3):
                best_prev = INF

                if i < n // 2:
                    # First half: only constraint is adjacent (with i-1)
                    for c in range(3):
                        if c != j:
                            if dp[i-1][c] < best_prev:
                                best_prev = dp[i-1][c]
                elif i == n // 2:
                    # Middle: constraint with i-1 (symmetric partner)
                    for c in range(3):
                        if c != j:
                            if dp[i-1][c] < best_prev:
                                best_prev = dp[i-1][c]
                else:
                    # Second half: constraint with symmetric partner k = n - 1 - i
                    k = n - 1 - i
                    for c in range(3):
                        if c != j:
                            if dp[k][c] < best_prev:
                                best_prev = dp[k][c]

                dp[i][j] = best_prev + cost[i][j]

        return min(dp[n-1])

