class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total_k = nums.count(k)

        # Collect distinct values present in nums to avoid unnecessary iterations
        distinct_vals = set(nums)

        ans_diff = -float('inf')

        # Iterate over each distinct value v that appears in the array
        for v in distinct_vals:
            # We want to find the subarray [i..j] that maximizes:
            # (count of v in [i..j]) - (count of k in [i..j])
            # This represents the net gain in the frequency of k after applying the operation with x = k - v.
            # Use Kadane's algorithm to find the maximum subarray sum.

            current_max = -float('inf')
            global_max = -float('inf')

            for num in nums:
                if num == v:
                    val = 1
                elif num == k:
                    val = -1
                else:
                    val = 0

                # First element of the subarray
                if current_max == -float('inf'):
                    current_max = val
                else:
                    # Either start a new subarray at this element or extend the previous
                    current_max = max(val, current_max + val)

                if current_max > global_max:
                    global_max = current_max

            if global_max > ans_diff:
                ans_diff = global_max

        # The total frequency of k after the optimal operation is:
        # total_k (original k's outside the subarray) + ans_diff (gain from transforming v's inside the subarray)
        return total_k + ans_diff

