    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        # Group indices by their value in nums1
        groups = {}
        for idx, val in enumerate(nums1):
            if val not in groups:
                groups[val] = []
            groups[val].append(idx)

        # Sort the unique values in ascending order
        sorted_vals = sorted(groups.keys())

        # Min-heap to store the k largest nums2 values seen so far
        top_k_heap = []
        current_sum = 0

        # Prepare the answer array
        answer = [0] * n

        for v in sorted_vals:
            # Step 1: Answer for all indices i where nums1[i] == v
            # At this point, top_k_heap contains all nums2[j] for j with nums1[j] < v
            if not top_k_heap:
                for i in groups[v]:
                    answer[i] = 0
            else:
                # Sum of the k largest elements seen so far (which are all from nums1[j] < v)
                for i in groups[v]:
                    answer[i] = current_sum

            # Step 2: Add indices with nums1[j] == v to the heap for future queries
            for idx in groups[v]:
                val = nums2[idx]
                if len(top_k_heap) < k:
                    heapq.heappush(top_k_heap, val)
                    current_sum += val
                else:
                    # If the new value is greater than the smallest in the top k, replace it
                    if val > top_k_heap[0]:
                        removed = heapq.heappop(top_k_heap)
                        current_sum -= removed
                        heapq.heappush(top_k_heap, val)
                        current_sum += val
                    # Else, ignore because this value is not in the top k yet

        return answer

