                else:
                    update(2 * node + 1, mid + 1, end, idx)
                tree[node] = max(tree[2 * node], tree[2 * node + 1])

        # Query: find the first index in [start, end] with value >= x
        def query(node, start, end, x):
            if tree[node] < x:
                return -1
            if start == end:
                return start
            mid = (start + end) // 2
            res = query(2 * node, start, mid, x)
            if res != -1:
                return res
            return query(2 * node + 1, mid + 1, end, x)

        # Build the tree initially
        build(1, 0, n - 1)

        unplaced_count = 0
        for f in fruits:
            pos = query(1, 0, n - 1, f)
            if pos == -1:
                unplaced_count += 1
            else:
                update(1, 0, n - 1, pos)

        return unplaced_count

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Check if the array is already all zeros
        if all(x == 0 for x in nums):
            return 0

        # Work on a copy of nums to simulate the process
        current_nums = nums[:]
        m = len(queries)

        # Try each k from 1 to m (number of queries)
        for k in range(1, m + 1):
            l, r, val = queries[k-1]
            # Apply the k-th query: decrement each index in [l, r] that has value >= val
            for j in range(l, r + 1):
                if current_nums[j] >= val:
                    current_nums[j] -= val

            # Check if all elements are zero after applying the query
            if all(x == 0 for x in current_nums):
                return k

        # If no k works, return -1
        return -1

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Calculate the total number of cells on the n x n deck
        total_cells = n * n

        # Calculate how many containers fit based on weight limit
        # We use integer division to get the floor value
        count_by_weight = maxWeight // w

        # The actual number of containers is limited by either the weight capacity 
        # or the physical space available on the deck.
        return min(count_by_weight, total_cells)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Build adjacency matrix or list for the graph
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection = len(set_i & set_j)

                if intersection >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Initialize visited array and connected components counter
        visited = [False] * n
        components = 0

        # DFS helper function
        def dfs(node, visited_stack):
            visited[node] = True
            visited_stack.append(node)

            for neighbor in adj[node]:
                if not visited[neighbor]:
                    dfs(neighbor, visited_stack)

        # Iterate over all nodes and start DFS if not visited
        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i, [])

        return components

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0
        n_s = len(s)
        n_t = len(t)

        # Precompute the substrings? No, we iterate.

        # To optimize, we can iterate over the possible lengths of the combined string? 
        # But it's not necessary.

        # We'll do the brute-force with early exit in the palindrome check.

        for i_start in range(n_s + 1):
            for i_end in range(i_start, n_s + 1):
                s_sub = s[i_start:i_end]
                len_s = len(s_sub)

                # We only consider t_sub with length at least max_len - len_s? 
                # But we don't know the length of t_sub yet.
                # Instead, we can iterate over t_sub and skip if len_s + len(t_sub) < max_len
                # But we don't know the length of t_sub until we pick it.

                # We can do:
                for j_start in range(n_t + 1):
                    for j_end in range(j_start, n_t + 1):
                        t_sub = t[j_start:j_end]
                        total_len = len_s + len(t_sub)
                        if total_len < max_len:
                            continue
                        if is_palindrome(s_sub + t_sub):
                            max_len = total_len
                            # Optimization: if total_len is the maximum possible (60), we can break?
                            # But 60 is the maximum, so we can break both loops?
                            if total_len == 60:
                                break
                        elif total_len > max_len:
                            max_len = total_len

                    # If we broke out of the innermost loop, we break out of the next loop too.
                    if total_len == 60:
                        break
                else:
                    continue
                break

        return max_len

    def is_palindrome(self, sub):
        n = len(sub)
        for i in range(n // 2):
            if sub[i] != sub[n - 1 - i]:
                return False
        return True

class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0

        # Check all adjacent pairs including the wrap-around pair (last and first)
        for i in range(n):
            # Compare element at index i with element at index (i + 1) % n
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff

        return max_diff

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count the frequency of each digit in the string
        from collections import Counter

        freq = Counter(s)

        # Iterate through adjacent pairs
        for i in range(len(s) - 1):
            first_digit = int(s[i])
            second_digit = int(s[i+1])

            # Check if digits are different
            if first_digit == second_digit:
                continue

            # Check if each digit appears exactly as many times as its numeric value
            if freq[first_digit] == first_digit and freq[second_digit] == second_digit:
                return s[i:i+2]

        return ""

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            # Determine the boundaries for comparison
            left_idx = i - k
            right_idx = i + k

            # Check if left index exists and get value if it does
            left_val = None
            if left_idx >= 0:
                left_val = nums[left_idx]

            # Check if right index exists and get value if it does
            right_val = None
            if right_idx < n:
                right_val = nums[right_idx]

            # Determine the threshold for 'strictly greater'
            # If both indices exist, must be > max(left, right)
            # If only one exists, must be > that one
            # If neither exists, condition is always true (threshold is effectively negative infinity)

            if left_val is not None and right_val is not None:
                threshold = max(left_val, right_val)
            elif left_val is not None:
                threshold = left_val
            elif right_val is not None:
                threshold = right_val
            else:
                threshold = float('-inf')

            if nums[i] > threshold:
                total_sum += nums[i]

        return total_sum

from typing import List

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total_area = 0
        for x, y, l in squares:
            total_area += l * l

        if total_area == 0:
            return 0.0

        half_total = total_area / 2.0

        # Sort squares by bottom-left y-coordinate
        squares.sort(key=lambda s: s[1])

        current_area_before = 0.0

        for x, y, l in squares:
            area_current = l * l
            if current_area_before + area_current >= half_total:
                needed = half_total - current_area_before
                return y + needed / l
            current_area_before += area_current

        return 0.0

class Solution:
    def reverseDegree(self, s: str) -> int:
        # Map each character to its reversed alphabet index: 'a'->26, 'b'->25, ..., 'z'->1
        char_to_val = {chr(ord('a') + i): 27 - i for i in range(26)}

        total = 0
        for idx, char in enumerate(s, start=1):  # 1-indexed position
            total += char_to_val[char] * idx

        return total

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Count total ones in the original string
        total_ones = s.count('1')

        # Parse the string into segments of consecutive identical characters
        segments = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == '1':
                j = i
                while j < n and s[j] == '1':
                    j += 1
                segments.append((j - i, '1'))
                i = j
            else:
                j = i
                while j < n and s[j] == '0':
                    j += 1
                segments.append((j - i, '0'))
                i = j

        # Initialize max_val with the case where no trade is performed
        max_val = total_ones
        num_segments = len(segments)

        # Iterate over segments that are '1' and check if they are surrounded by '0's
        for idx in range(num_segments):
            if segments[idx][1] == '1':
                # Check if there is a previous and next segment
                if idx > 0 and idx < num_segments - 1:
                    prev_type = segments[idx-1][1]
                    next_type = segments[idx+1][1]
                    if prev_type == '0' and next_type == '0':
                        # Calculate candidate: original ones + left zero block + right zero block
                        candidate = total_ones + segments[idx-1][0] + segments[idx+1][0]
                        if candidate > max_val:
                            max_val = candidate

        return max_val
